; plate.asm -- appendix E: every ink on every paper
; generated by genE.py
        INCLUDE "msx.inc"
        OUTPUT "plate.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
colour  EQU VARS                ; the cell's colour byte, ink and paper
; Fifteen rows, one for each ink, from row 5; in each, fifteen cells of two
; characters from column 1, one for each paper: the ink's digit and the paper's.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld d, 5                 ; D: the row of characters
        ld b, 1                 ; B: the ink
.ink:   ld e, 1                 ; E: the column of characters
        ld c, 1                 ; C: the paper
.paper: ld a, b
        rlca
        rlca
        rlca
        rlca
        or c
        ld (colour), a          ; ink in the high four bits, paper in the low
        ld a, b
        call cell               ; the ink's digit
        inc e
        ld a, c
        call cell               ; the paper's digit
        inc e
        inc c
        ld a, c
        cp 16
        jr nz, .paper
        inc d
        inc b
        ld a, b
        cp 16
        jr nz, .ink
        VDP_REG 1, $C0          ; the display on: the plate is finished
done:   jr done

; cell: the character at row D, column E: digit A in the ink and paper of
; (colour). The BIOS's layout: its pattern bytes at D x 256 + E x 8, its
; colours $2000 further on (Appendix D). Keeps BC, DE.
cell:   push bc
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        ld bc, digits
        add hl, bc              ; HL: the digit's eight bytes
        ld a, e
        add a, a
        add a, a
        add a, a
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a       ; write from D x 256 + E x 8
        ld b, 8
.pat:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .pat
        ld a, e
        add a, a
        add a, a
        add a, a
        out (VDP_CTRL), a
        ld a, d
        or $60
        out (VDP_CTRL), a       ; and from $2000 more
        ld a, (colour)
        ld b, 8
.col:   out (VDP_DATA), a
        djnz .col
        pop bc
        ret

; the sixteen digits, 0 to F, eight bytes each
digits: db %00111000, %01000100, %01001100, %01010100, %01100100, %01000100, %00111000, %00000000 ; 0
        db %00010000, %00110000, %00010000, %00010000, %00010000, %00010000, %00111000, %00000000 ; 1
        db %00111000, %01000100, %00000100, %00001000, %00010000, %00100000, %01111100, %00000000 ; 2
        db %01111100, %00001000, %00010000, %00001000, %00000100, %01000100, %00111000, %00000000 ; 3
        db %00001000, %00011000, %00101000, %01001000, %01111100, %00001000, %00001000, %00000000 ; 4
        db %01111100, %01000000, %01111000, %00000100, %00000100, %01000100, %00111000, %00000000 ; 5
        db %00011000, %00100000, %01000000, %01111000, %01000100, %01000100, %00111000, %00000000 ; 6
        db %01111100, %00000100, %00001000, %00010000, %00100000, %00100000, %00100000, %00000000 ; 7
        db %00111000, %01000100, %01000100, %00111000, %01000100, %01000100, %00111000, %00000000 ; 8
        db %00111000, %01000100, %01000100, %00111100, %00000100, %00001000, %00110000, %00000000 ; 9
        db %00111000, %01000100, %01000100, %01111100, %01000100, %01000100, %01000100, %00000000 ; A
        db %01111000, %01000100, %01000100, %01111000, %01000100, %01000100, %01111000, %00000000 ; B
        db %00111000, %01000100, %01000000, %01000000, %01000000, %01000100, %00111000, %00000000 ; C
        db %01111000, %01000100, %01000100, %01000100, %01000100, %01000100, %01111000, %00000000 ; D
        db %01111100, %01000000, %01000000, %01111000, %01000000, %01000000, %01111100, %00000000 ; E
        db %01111100, %01000000, %01000000, %01111000, %01000000, %01000000, %01000000, %00000000 ; F

        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
